def _safe_phase(name: str, func: Callable[[], Any]) -> Any:
"""Run one bootstrap phase and return a receipt instead of raising."""
started = time.time()
try:
value = func()
if isinstance(value, dict):
value.setdefault("phase", name)
value.setdefault("duration_ms", int((time.time() - started) * 1000))
return value
except Exception as exc:
return {
"phase": name,
"status": "error",
"error": str(exc),
"duration_ms": int((time.time() - started) * 1000),
}
